            return 2
        else:
            return 3

    def normalize_angle(angle):
        while angle < 0:
            angle += 2 * pi
        while angle >= 2 * pi:
            angle -= 2 * pi
        return angle

    quadrant_vectors = {}
    for i, (x, y) in enumerate(vectors):
        quadrant = get_quadrant(x, y)
        if quadrant not in quadrant_vectors:
            quadrant_vectors[quadrant] = []
        quadrant_vectors[quadrant].append((i + 1, atan2(y, x)))

    min_angle = float('inf')
    min_pair = (-1, -1)

